import json, os, urllib.request, urllib.error

TOKEN = os.environ['CLOUDFLARE_API_TOKEN']
ZONE_ID = '93c36852d356be51548b4c0644df4c6c'
ZONE = 'kuchup.com'
BASE = 'https://api.cloudflare.com/client/v4'
SPF = 'v=spf1 include:_spf.mx.cloudflare.net include:_spf.google.com ~all'
DMARC = 'v=DMARC1; p=none; rua=mailto:hello@kuchup.com'
GSC_PREFIX = 'google-site-verification='

def call(method, path, body=None):
    data = None if body is None else json.dumps(body).encode()
    req = urllib.request.Request(
        BASE + path, data=data, method=method,
        headers={'Authorization': f'Bearer {TOKEN}', 'Content-Type': 'application/json'},
    )
    try:
        with urllib.request.urlopen(req) as resp:
            return resp.status, json.load(resp)
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read().decode())

# List apex TXT
code, txts = call('GET', f'/zones/{ZONE_ID}/dns_records?type=TXT&name={ZONE}&per_page=100')
records = txts.get('result') or []
print('apex_txt_count', len(records))
spf_recs = []
gsc_recs = []
other = []
for r in records:
    content = r.get('content', '').strip('"')
    print(' TXT', content[:80], 'id=', r['id'][:8])
    if content.startswith('v=spf1'):
        spf_recs.append(r)
    elif content.startswith(GSC_PREFIX):
        gsc_recs.append(r)
    else:
        other.append(r)

# Ensure single SPF with Google include
if len(spf_recs) == 0:
    code, payload = call('POST', f'/zones/{ZONE_ID}/dns_records', {
        'type': 'TXT', 'name': ZONE, 'content': SPF, 'ttl': 1,
    })
    print('create_spf', code, payload.get('success'), (payload.get('errors') or [{}])[0].get('message'))
elif len(spf_recs) == 1:
    cur = spf_recs[0]['content'].strip('"')
    if 'include:_spf.google.com' in cur and 'include:_spf.mx.cloudflare.net' in cur:
        print('spf_ok', cur)
    else:
        code, payload = call('PUT', f'/zones/{ZONE_ID}/dns_records/{spf_recs[0]["id"]}', {
            'type': 'TXT', 'name': ZONE, 'content': SPF, 'ttl': 1,
        })
        print('update_spf', code, payload.get('success'), SPF)
else:
    # keep first, merge into desired SPF, delete extras
    keep = spf_recs[0]
    code, payload = call('PUT', f'/zones/{ZONE_ID}/dns_records/{keep["id"]}', {
        'type': 'TXT', 'name': ZONE, 'content': SPF, 'ttl': 1,
    })
    print('merge_spf', code, payload.get('success'))
    for extra in spf_recs[1:]:
        code, payload = call('DELETE', f'/zones/{ZONE_ID}/dns_records/{extra["id"]}')
        print('delete_extra_spf', code, payload.get('success'))

print('gsc_intact', bool(gsc_recs), 'count', len(gsc_recs))

# DMARC
code, dmarc_list = call('GET', f'/zones/{ZONE_ID}/dns_records?type=TXT&name=_dmarc.{ZONE}&per_page=20')
drecs = dmarc_list.get('result') or []
if not drecs:
    code, payload = call('POST', f'/zones/{ZONE_ID}/dns_records', {
        'type': 'TXT', 'name': f'_dmarc.{ZONE}', 'content': DMARC, 'ttl': 1,
    })
    print('create_dmarc', code, payload.get('success'), (payload.get('errors') or [{}])[0].get('message'))
else:
    print('dmarc_exists', drecs[0].get('content'))

# List rules summary (no personal emails)
code, rules = call('GET', f'/zones/{ZONE_ID}/email/routing/rules')
for r in rules.get('result') or []:
    matchers = r.get('matchers')
    actions = [a.get('type') for a in (r.get('actions') or [])]
    print('rule', r.get('name'), 'enabled=', r.get('enabled'), 'matchers=', matchers, 'actions=', actions)

# Try zone settings edit path - list zone settings email?
code, payload = call('GET', f'/zones/{ZONE_ID}/email/routing')
print('routing_settings', code, (payload.get('errors') or [{}])[0].get('message'), 'result=', payload.get('result'))

# DKIM?
code, dkim = call('GET', f'/zones/{ZONE_ID}/dns_records?type=TXT&name=cf2024-1._domainkey.{ZONE}')
print('dkim', [(r.get('name'), r.get('content')[:60]) for r in (dkim.get('result') or [])])
